#!/usr/bin/env python3
"""Merge user data from JSON, CSV, and Parquet sources."""

import json
from datetime import date, datetime
from pathlib import Path

import pandas as pd

SOURCE_FILES = {
    "source_a": "/data/source_a/users.json",
    "source_b": "/data/source_b/users.csv",
    "source_c": "/data/source_c/users.parquet",
}

# Priority order: source_a > source_b > source_c
PRIORITY = ["source_a", "source_b", "source_c"]

FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "name": ["full_name", "name", "userName"],
    "email": ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]
CONFLICT_FIELDS = ["name", "email", "created_date", "status"]


def is_missing(value):
    if value is None:
        return True
    try:
        result = pd.isna(value)
    except (TypeError, ValueError):
        return False
    return bool(result) if isinstance(result, (bool, type(pd.NA))) else False


def read_json(path):
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
    if isinstance(data, dict):
        for key in ("users", "data", "records", "items"):
            if key in data and isinstance(data[key], list):
                return pd.DataFrame(data[key])
        return pd.DataFrame([data])
    return pd.DataFrame(data)


def read_source(path):
    path = str(path)
    if path.lower().endswith(".json"):
        return read_json(path)
    if path.lower().endswith(".csv"):
        return pd.read_csv(path)
    if path.lower().endswith(".parquet"):
        return pd.read_parquet(path)
    raise ValueError(f"Unsupported file type: {path}")


def normalize_status(value):
    if is_missing(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip()
    lowered = text.lower()
    if lowered in {"true", "1", "yes", "y", "active", "enabled"}:
        return "active"
    if lowered in {"false", "0", "no", "n", "inactive", "disabled"}:
        return "inactive"
    return text


def normalize_date(value):
    if is_missing(value):
        return None
    if isinstance(value, pd.Timestamp):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, (datetime, date)):
        return value.strftime("%Y-%m-%d")
    text = str(value).strip()
    if not text:
        return None
    try:
        parsed = pd.to_datetime(text, errors="raise")
    except (ValueError, TypeError):
        return text
    return parsed.strftime("%Y-%m-%d")


def normalize_text(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    return text or None


def normalize_user_id(value):
    if is_missing(value):
        return None
    if isinstance(value, bool):
        raise ValueError(f"Invalid user_id: {value!r}")
    try:
        return int(value)
    except (TypeError, ValueError):
        return int(float(str(value).strip()))


def get_field(row, aliases):
    for alias in aliases:
        if alias in row and not is_missing(row[alias]):
            return row[alias]
    return None


def normalize_records(source_name, frame):
    records = []
    for _, row in frame.iterrows():
        record = {}
        for field, aliases in FIELD_ALIASES.items():
            value = get_field(row, aliases)
            if field == "user_id":
                record[field] = normalize_user_id(value)
            elif field == "created_date":
                record[field] = normalize_date(value)
            elif field == "status":
                record[field] = normalize_status(value)
            else:
                record[field] = normalize_text(value)
        if record["user_id"] is not None:
            record["_source"] = source_name
            records.append(record)
    return records


def main():
    all_records = []
    for source_name in PRIORITY:
        frame = read_source(SOURCE_FILES[source_name])
        all_records.extend(normalize_records(source_name, frame))

    by_user = {}
    for record in all_records:
        by_user.setdefault(record["user_id"], {})[record["_source"]] = record

    merged_rows = []
    conflicts = []
    for user_id in sorted(by_user):
        source_records = by_user[user_id]
        merged = {"user_id": user_id}
        for field in CONFLICT_FIELDS:
            values = {}
            for source_name in PRIORITY:
                if source_name not in source_records:
                    continue
                value = source_records[source_name].get(field)
                if value is not None:
                    values[source_name] = value

            selected = None
            for source_name in PRIORITY:
                if source_name in values:
                    selected = values[source_name]
                    break
            merged[field] = selected

            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,
                        "selected": selected,
                    }
                )
        merged_rows.append(merged)

    merged_frame = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)
    merged_frame["user_id"] = merged_frame["user_id"].astype("int64")
    for column in ["name", "email", "created_date", "status"]:
        merged_frame[column] = merged_frame[column].astype("object")

    output_dir = Path("/app")
    output_dir.mkdir(parents=True, exist_ok=True)
    merged_frame.to_parquet(output_dir / "merged_users.parquet", index=False)

    conflict_report = {
        "total_conflicts": len(conflicts),
        "conflicts": conflicts,
    }
    with open(output_dir / "conflicts.json", "w", encoding="utf-8") as handle:
        json.dump(conflict_report, handle, indent=2, ensure_ascii=False)
        handle.write("\n")

    print(f"Wrote {len(merged_frame)} users and {len(conflicts)} conflicts.")


if __name__ == "__main__":
    main()
PYEOF
